type Language = "en" | "fr" | "km";

const months = ["មករា", "កុម្ភៈ", "មីនា", "មេសា", "ឧសភា", "មិថុនា", "កក្កដា", "សីហា", "កញ្ញា", "តុលា", "វិច្ឆិកា", "ធ្នូ"];
const weekdays = ["អាទិត្យ", "ចន្ទ", "អង្គារ", "ពុធ", "ព្រហស្បតិ៍", "សុក្រ", "សៅរ៍"];
const englishWeekdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const khmerDigits = (value: string) => value.replace(/\d/g, (digit) => "០១២៣៤៥៦៧៨៩"[Number(digit)]);

export function localizedDate(language: Language, options: Intl.DateTimeFormatOptions): Pick<Intl.DateTimeFormat, "format"> {
  if (language !== "km" || Intl.DateTimeFormat.supportedLocalesOf(["km"]).length) return new Intl.DateTimeFormat(language, options);
  const formatter = new Intl.DateTimeFormat("en-GB", options);
  const monthFormatter = new Intl.DateTimeFormat("en-GB", { timeZone: options.timeZone, month: "numeric" });
  const weekdayFormatter = new Intl.DateTimeFormat("en-GB", { timeZone: options.timeZone, weekday: "long" });
  const offsetFormatter = new Intl.DateTimeFormat("en-GB", { timeZone: options.timeZone, timeZoneName: "shortOffset" });
  return {
    format: (value) => formatter.formatToParts(value).map((part) => {
      if (part.type === "month" && /[A-Za-z]/.test(part.value)) {
        const index = Number(monthFormatter.format(value)) - 1;
        return months[index];
      }
      if (part.type === "weekday") {
        const index = englishWeekdays.indexOf(weekdayFormatter.format(value));
        return weekdays[index];
      }
      if (part.type === "dayPeriod") return part.value.toLowerCase().startsWith("a") ? "ព្រឹក" : "ល្ងាច";
      if (part.type === "era") return /^b/i.test(part.value) ? "មុន គ.ស." : "គ.ស.";
      if (part.type === "timeZoneName") return khmerDigits(offsetFormatter.formatToParts(value).find((item) => item.type === "timeZoneName")!.value);
      return khmerDigits(part.value.replace(" at ", " ម៉ោង "));
    }).join(""),
  };
}

export function localizedNumber(language: Language, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  if (language !== "km" || Intl.NumberFormat.supportedLocalesOf(["km"]).length) return new Intl.NumberFormat(language, options);
  return new Intl.NumberFormat("en", { ...options, numberingSystem: "khmr" });
}
